WITH joined AS (SELECT o.order_id, o.member_id, o.store_id, m.home_store_id, o.ordered_at, o.status, o.gross_cents, o.paid_cents, o.refund_cents, o.quantity, o.channel FROM {{ ref('orders') }} AS o LEFT JOIN {{ ref('members') }} AS m ON o.member_id = m.member_id), valid_sequences AS (SELECT order_id, ROW_NUMBER() OVER (PARTITION BY member_id ORDER BY ordered_at, order_id) AS valid_order_seq FROM joined WHERE status = 'paid' AND paid_cents - refund_cents > 0) SELECT j.order_id, j.member_id, j.store_id, j.home_store_id, j.ordered_at, j.status, j.gross_cents, j.paid_cents, j.refund_cents, j.quantity, j.channel, v.valid_order_seq FROM joined AS j LEFT JOIN valid_sequences AS v ON j.order_id = v.order_id